import { bls12_381 } from '@noble/curves/bls12-381.js';

const { G1, G2, fields, pairing, shortSignatures, utils } = bls12_381;
const { Fr, Fp12 } = fields;

const MOD = Fr.ORDER;

// ── Finite-field helpers (all modulo Fr.ORDER) ──
function mod(n) { return ((n % MOD) + MOD) % MOD; }
function powMod(base, exp) { /* standard modular exponentiation */ }
function inv(a) { return powMod(a, MOD - 2n); }
function bytesToBigInt(bytes) { /* big-endian 32 bytes → BigInt */ }
function bigIntToBytes(n) { /* BigInt → 32-byte big-endian Uint8Array */ }

// ── Lagrange coefficient λ_i for participant i given set S ──
// λ_i = Π_{j∈S, j≠i} (0 − j) / (i − j)   (mod q)
function lagrangeCoefficient(i, S) { /* ... */ }

// ── Shamir polynomial evaluation (Horner) ──
function evaluatePolynomial(coeffs, x) { /* ... */ }

// ═══════════════════════════════════════════════════
//  Public API
// ═══════════════════════════════════════════════════

// 1. Key generation (trusted dealer): t-of-n threshold
export function thresholdKeygen(t, n) {
  const mskBytes = utils.randomSecretKey();
  const masterSecretKey = bytesToBigInt(mskBytes);
  const masterPublicKey = G2.Point.BASE.multiply(masterSecretKey);

  // Random polynomial of degree t-1: f(x) = s + a₁·x + … + a_{t-1}·x^{t-1}
  const coeffs = [masterSecretKey];
  for (let i = 1; i < t; i++) {
    coeffs.push(bytesToBigInt(utils.randomSecretKey()));
  }

  const shares = [];
  for (let id = 1; id <= n; id++) {
    const secret = evaluatePolynomial(coeffs, id);
    shares.push({ id, secret, publicKey: G2.Point.BASE.multiply(secret) });
  }
  return { masterSecretKey, masterPublicKey, shares };
}

// 2. Partial signing: σ_i = share · H(m)
export function partialSign(secretShare, msg) {
  return G1.hashToCurve(msg).multiply(secretShare);
}

// 3. Lagrange-weighted aggregation of t partial signatures
export function aggregateSignatures(partials) {
  if (partials.length < 1) throw new Error('need at least one partial signature');
  const ids = [...new Set(partials.map(p => BigInt(p.id)))];
  if (ids.length !== partials.length) throw new Error('duplicate IDs');
  let aggregated = G1.Point.ZERO;
  for (const { id, signature } of partials) {
    aggregated = aggregated.add(signature.multiply(lagrangeCoefficient(id, ids)));
  }
  return aggregated;
}

// 4. Verification: e(σ, G₂)  ==  e(H(m), mpk)
export function verify(sig, mpk, msg) {
  const h = G1.hashToCurve(msg);
  return Fp12.eql(pairing(sig, G2.Point.BASE), pairing(h, mpk));
}

// 5. Serialization helpers
export function pointToBytesG1(pt)    { return pt.toBytes(); }        // 48 bytes
export function bytesToPointG1(bytes) { return G1.Point.fromBytes(bytes); }
export function pointToBytesG2(pt)    { return pt.toBytes(); }        // 96 bytes
export function bytesToPointG2(bytes) { return G2.Point.fromBytes(bytes); }
export function signatureToHex(sig)   { return sig.toHex(); }
```

**Design choices:**
- **Short-signature variant**: σ ∈ G₁ (48 bytes), PK ∈ G₂ (96 bytes) — the efficient minimal-pubkey variant of BLS12-381.
- **Trusted dealer**: A single dealer generates the master secret, builds a degree-(t−1) polynomial, and distributes shares `f(1) … f(n)`.
- **Lagrange reconstruction**: At aggregation time, `λ_i` coefficients are computed on the fly over the actual set of signers so any subset of size ≥ t works.
- **Fp12.eql** for pairing comparison — necessary because Fp12 elements are objects, not primitives.

